// ChemEditAPI.ts
init_ChemDataEngine();
init_SharedEln();
function buildChemEditAPI(plugin) {
  const getKetcherSafely = async () => {
    if (!plugin.headlessKetcher) {
      plugin.bootHeadlessKetcher();
      await new Promise((r12) => setTimeout(r12, 1500));
    }
    return plugin.headlessKetcher;
  };
  return {
    openEditor: (data, format3, onSave) => plugin.openKetcherModal(data, format3, onSave),
    renderStructure: async (data, width2, height2) => await plugin.renderMoleculeToPreview(data, "smiles", false, width2, height2),
    ketcher: {
      openEditor: (data, format3, onSave) => plugin.openKetcherModal(data, format3, onSave),
      getHeadless: async () => await getKetcherSafely(),
      convertFormat: async (data, outputFormat) => {
        const k7 = await getKetcherSafely();
        await k7.setMolecule(data);
        if (outputFormat === "svg") return await k7.generateImage(await k7.getKet(), { outputFormat: "svg" });
        if (outputFormat === "smiles") return await k7.getSmiles();
        return await k7.getMolfile();
      }
    },
    data: {
      getProperties: (smiles) => ChemDataEngine.getPropertiesFromSmiles(smiles),
      isSubstructureMatch: (target, query) => ChemDataEngine.isSubstructureMatch(target, query),
      molToSmiles: (mol) => ChemDataEngine.molToSmiles(mol)
    },
    library: {
      getCompounds: async () => await getCompoundLibrary(plugin),
      addCompound: async (name, smiles) => await addCompoundToLibrary2(plugin, name, smiles)
    },
    eln: {
      createExperiment: async (code, targetFolder) => await createNewElnExperiment(plugin.app, code, targetFolder || plugin.settings.elnDirectory || "/", plugin.settings.elnSections)
    }
  };
}

